# -*- coding: utf-8 -*-
"""Build a self-contained illustrated report from the captured HTTP evidence."""
from pathlib import Path
import html,json
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'reports';OUT.mkdir(exist_ok=True)
evidence=json.loads((OUT/'verification-evidence.json').read_text())

def diagram(title,steps,caption):
    n=len(steps);w=1080;box=(w-80-(n-1)*28)/n
    nodes=[]
    for i,(a,b) in enumerate(steps):
        x=40+i*(box+28)
        nodes.append(f'<rect x="{x}" y="56" width="{box}" height="104" rx="12" fill="{["#e5f1f5","#edf0fb","#e9f4ec"][i%3]}" stroke="#bdd0d9"/><text x="{x+box/2}" y="97" text-anchor="middle" font-size="18" font-weight="700">{html.escape(a)}</text><text x="{x+box/2}" y="127" text-anchor="middle" font-size="13" fill="#4c6575">{html.escape(b)}</text>')
        if i<n-1:nodes.append(f'<path d="M{x+box+3} 108 h20" stroke="#44879b" stroke-width="2" marker-end="url(#arrow)"/>')
    svg=f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1080 215" role="img" aria-label="{title}"><defs><marker id="arrow" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="#44879b"/></marker></defs><rect width="1080" height="215" fill="#fafcfd"/><g font-family="PingFang SC,Microsoft YaHei,sans-serif" fill="#16374a"><text x="40" y="30" font-size="18" font-weight="700">{title}</text>{"".join(nodes)}<text x="40" y="193" font-size="14" fill="#4c6575">{caption}</text></g></svg>'
    return svg
figures=[diagram('图 1 · 平台整体架构',[('身份与应用','Bearer / app_id'),('模板与 Skill','绑定配置 / 全文加载'),('知识库检索','本班 Top 4 切片'),('LLM 与工具','流式回答 / 调用闭环'),('证据与会话','SSE / SQLite 审计')],'知识库是否开启由应用配置决定；教案、练习应用可以在不检索资料时调用模型。'),diagram('图 2 · 真正进入模型的内容',[('system','展开模板 + 教师设定'),('Skill 正文','仅绑定技能的全部正文'),('history','最近 12 条完整消息'),('user','问题 + 命中证据'),('tools','授权工具 JSON Schema')],'知识库原文件、未命中切片、MCP 服务实现代码和认证密钥不会被自动拼入请求。'),diagram('图 3 · MCP 与模型的两次请求',[('MCP 初始化','initialize / tools/list'),('LLM 第 1 次','messages + tools'),('模型选择工具','assistant.tool_calls'),('后端执行','MCP tools/call'),('LLM 第 2 次','role:tool + 结果')],'本地验证：school__lookup 返回“周三科学课：磁铁实验。”；该内容首次出现在第 2 次模型请求。')]
for i,fig in enumerate(figures,1):(OUT/f'figure-{i}.svg').write_text(fig)

style='''*{box-sizing:border-box}body{margin:0;background:#eef3f6;color:#183342;font:16px/1.85 -apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei",sans-serif}main{max-width:1140px;margin:36px auto;background:#fff;padding:50px 58px;border-radius:18px;box-shadow:0 12px 40px #18334212}h1{font-size:34px;line-height:1.4;margin:10px 0 16px}h2{font-size:24px;border-bottom:2px solid #dce8ed;padding-bottom:10px;margin-top:38px}h3{font-size:19px;color:#16677c;margin-top:26px}.eyebrow{font-size:12px;letter-spacing:2px;color:#32798d}.meta{color:#5b7383}.callout{background:#edf6f8;border-left:5px solid #32889a;padding:18px 22px;margin:24px 0}.warning{background:#fff5de;border-left-color:#bc8b20}table{width:100%;border-collapse:collapse;margin:18px 0;font-size:14px}td,th{border:1px solid #dce6ec;padding:11px 13px;text-align:left;vertical-align:top}th{background:#edf4f7}pre{background:#102c3a;color:#d9edf5;padding:20px;border-radius:10px;white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.7 ui-monospace,monospace;max-height:700px;overflow:auto}code{font-family:ui-monospace,monospace;font-size:.9em}svg{width:100%;height:auto;display:block;margin:24px 0;border:1px solid #e1e9ee;border-radius:12px}.metrics{display:flex;gap:16px}.metric{flex:1;background:#f2f7f9;padding:18px;border-radius:12px}.metric b{font-size:28px;color:#19758a;display:block}summary{cursor:pointer;font-weight:600;color:#16677c}details{margin:18px 0}a{color:#146d88}footer{border-top:1px solid #dce6ec;margin-top:40px;padding-top:18px;font-size:13px;color:#5b7383}@media(max-width:760px){main{margin:0;padding:24px 18px;border-radius:0}h1{font-size:26px}.metrics{display:block}td,th{padding:6px}}@media print{body{background:white}main{margin:0;padding:10px;box-shadow:none}details pre{max-height:none}h2,h3,svg{break-inside:avoid}table{font-size:11px}pre{font-size:10px}}'''
intro='''<div class="eyebrow">CAMPUSCLAW / IMPLEMENTATION & VERIFICATION</div><h1>智能教学 AI 应用平台<br>功能补齐与 LLM 请求验证报告</h1><p class="meta">日期：2026-10-27（Asia/Shanghai） · 依据：当前代码、自动化断言、本机 HTTP 捕获</p><div class="callout"><b>核心结论</b>：已新增三种 AI 应用、可编辑提示词模板、可上传声明式 Skill、HTTP 外部工具与 MCP 接入，并提供逐次 LLM 请求/响应记录。模板及绑定 Skill 全文进入系统消息；知识库仅传命中片段；工具定义与工具执行结果分阶段传递。</div><div class="metrics"><div class="metric"><b>3</b>内置 AI 应用</div><div class="metric"><b>39 / 40</b>通过 / 总测试（1 项跳过）</div><div class="metric"><b>5 / 5</b>验证问题逐项给出证据</div></div>'''
body='''<h2>1. 项目简要介绍与功能对照</h2><p>CampusClaw 是面向教师与学生的班级教学平台。前端为原生 JavaScript，后端为 Python ThreadingHTTPServer；SQLite 保存账号、资料、切片、会话、应用配置与审计，FTS5 负责关键词检索，可选 FastEmbed + Qdrant 提供向量/混合检索。认证采用可撤销随机 Bearer Token（8 小时有效），班级与角色来自服务端会话。</p><table><tr><th>要求</th><th>修改前</th><th>修改后与入口</th></tr><tr><td>多个 AI 应用</td><td>单一知识问答</td><td>知识问答、教案设计、练习与计算；问答页新增应用选择器，可另建应用。</td></tr><tr><td>提示词模板</td><td>仅本班教师提示词</td><td>三份内置模板；教师可保存新模板、绑定应用；支持 {{class_name}}、{{question}} 单次展开。</td></tr><tr><td>知识库检索</td><td>已支持</td><td>保留关键词、向量、混合检索；应用可绑定/关闭本班知识库；最多取 4 个证据切片。</td></tr><tr><td>内置及上传 Skill</td><td>只有引导开关</td><td>三份内置 Markdown 技能；支持上传文件、按班级存储、应用绑定、工具声明。</td></tr><tr><td>外部工具与 MCP</td><td>无</td><td>内置安全算术工具；管理员环境配置 HTTP 工具和 MCP；教师可绑定已接入工具。</td></tr></table>'''+figures[0]+'''<h2>2. 验证方法与可信边界</h2><p>使用临时数据库启动真实应用 HTTP 服务，以及本机确定性 LLM 与 MCP 测试服务。请求实际经过 urllib HTTP 编码、SSE 解析、工具分发、会话保存和鉴权接口；测试比较接收端捕获的 JSON 与平台记录，未只停留在对函数的模拟调用。</p><p>检索样本同时放入磁铁材料和带 <code>UNRELATED_SENTINEL</code> 标记的大段无关资料；技能使用尾部 <code>SKILL_END_SENTINEL</code> 标记。工具测试验证计算结果 60、MCP 完整初始化和结果回传。</p><div class="callout warning"><b>范围说明</b>：这验证了本机协议和执行链路，不代表真实商业模型的生成质量、工具选择准确率或任意 MCP 服务兼容性。本次未使用真实付费密钥或用户资料。真实 Qdrant 边界测试因依赖缺失跳过；浏览器通道连接失败，页面点击与布局没有完成验收。</div><h2>3. 验证一：每次传给 LLM 的参数及返回内容</h2><p>新应用入口为 <code>POST /api/chat</code>，携带 <code>app_id</code>、<code>question</code>、可选 <code>conversation_id</code>。平台发送 POST 至配置的 <code>AI_BASE_URL + /chat/completions</code>，认证请求头只在后端使用，不写入报告或 traces。</p><table><tr><th>字段</th><th>实际内容</th></tr><tr><td>model</td><td>来自 AI_MODEL；本次捕获值为 fixture-model。</td></tr><tr><td>messages</td><td>system：已展开模板、教师设定、技能全文和规则；其后最多 12 条完整历史；user：当前问题与本轮证据。</td></tr><tr><td>stream / max_tokens / temperature</td><td>true / 1200 / 0.2</td></tr><tr><td>tools / tool_choice</td><td>仅有授权工具时加入函数名称、描述和参数 Schema，以及 auto；无工具时省略。</td></tr><tr><td>返回内容</td><td>SSE data JSON：choices[].delta.content 或 delta.tool_calls；finish_reason；可选 usage；以 [DONE] 结束。平台保存解析后的原始 JSON 片段及汇总 assistant 消息。</td></tr></table><p><b>模板内容会一并传递。</b> 验证自定义模板 <code>TEMPLATE_SENTINEL {{class_name}} {{question}}</code>，捕获 system 中实际为 <code>TEMPLATE_SENTINEL A班 主题ABC</code>。知识库案例返回 <code>磁铁吸引铁钉，木块不被吸引。[1]</code>；这是测试服务的确定性响应，不能用作真实模型能力证明。</p>'''+figures[1]+'''<h2>4. 验证二：绑定知识库是否传全部内容</h2><p><b>不会默认传全库。</b> 检索范围来自会话班级，按当前问题召回最多 4 个切片，组装 citation、title、chunk_index、start_char、end_char、text。本次仅命中 1 片；完整请求中未出现无关材料标记。每片默认不超过 800 个 Unicode 字符，因此本轮正文证据通常至多约 3200 字符，不包含 JSON 元数据和历史。</p><p>如果知识库本身很小，命中切片可能恰好覆盖其全部正文，但代码没有“无条件传全库”的逻辑。历史消息可能间接保留以前的证据信息。无命中时返回固定提示，trace.llm 为空，不调用模型。向量或混合模式未就绪时明确报错，不静默降级。</p><h2>5. 验证三：绑定 Skill 是否传全部内容</h2><p><b>本实现对每个绑定技能传入完整 Markdown 正文。</b> 技能正文拼入 system，未绑定技能不加入；每份正文上限 16000 字符，应用最多绑定 8 份。上传样例正文含首部、步骤与尾部标记，测试断言完整字符串出现在第一条模型消息中，而未绑定的内置引导技能正文不存在。</p><p>配置中的 id、name、tools 用于后端管理；技能工具声明转换成允许调用的函数 Schema。这里不是“按需读取 Skill 文件”的渐进式加载；也不支持 ZIP 附件目录、上传脚本执行或通用操作系统代理。报告中的“全文”指本平台上传的单份 Markdown 正文。</p><h2>6. 验证四：具体 Skill 的执行逻辑</h2><p>执行分为两层：Markdown 说明由模型按步骤理解；需要确定性操作时，模型返回 tool_calls，由后端真实执行。平台不会把 Markdown 当 Python 或 Shell 程序运行，也不会仅凭生成一段文字宣称工具执行成功。</p><ol><li>根据当前应用绑定加载技能，合并应用 tool_ids 和技能 tools，生成授权集合。</li><li>发送技能指令及工具 Schema，解析流式函数名和 arguments。</li><li>校验工具名在授权集合内、JSON 参数为对象、必填项和基础类型/长度/枚举约束。</li><li>内置 calculate 用 AST 白名单执行 +、-、*、/、%；禁止函数调用、导入和幂运算，并限制深度和数值。</li><li>HTTP 工具 POST JSON；MCP 工具执行 tools/call。结果写入 role:tool，携带与 assistant.tool_calls 对应的 tool_call_id，再次请求模型。</li><li>每轮最多 4 次调用、最多 3 轮工具执行（最多 4 次模型请求）；异常标记 error，拒绝未授权工具，残缺流不会标记完成。</li></ol><p>实测练习技能请求 calculate({"expression":"(12+8)*3"})，后端返回 {"value":60}，随后第二次 LLM 请求包含该结果。模型“是否遵循自然语言工作流”仍需真实模型评测，不能由工具执行成功推断。</p><h2>7. 验证五：MCP 集成后传给 LLM 的参数</h2>'''+figures[2]+'''<p>MCP 服务并不直接收取用户对话。平台先作为 MCP 客户端完成 <code>initialize → notifications/initialized → tools/list</code>，将管理员白名单中的工具转换成 LLM <code>tools</code>。MCP 地址、认证头和服务实现代码不会自动传给 LLM。</p><table><tr><th>阶段</th><th>实际报文内容</th></tr><tr><td>LLM 第一次</td><td>标准模型参数 + messages + tools:[{type:function,function:{name:school__lookup,description:查询演示课表,parameters:…}}] + tool_choice:auto</td></tr><tr><td>模型返回</td><td>assistant.tool_calls，id=call_fixture_1，name=school__lookup，arguments={"topic":"科学"}</td></tr><tr><td>平台调用 MCP</td><td>JSON-RPC 2.0，method=tools/call，params={name:lookup,arguments:{topic:科学}}；不发送整个对话。</td></tr><tr><td>MCP 返回</td><td>content:[{type:text,text:周三科学课：磁铁实验。}], isError:false</td></tr><tr><td>LLM 第二次</td><td>保留前次 messages，追加 assistant.tool_calls 以及 role:tool、tool_call_id、JSON 字符串结果；再次携带 tools。</td></tr></table><p><b>断言结论</b>：第一轮 LLM 请求不含“周三科学课”，第二轮请求的 tool 消息才出现它。未被调用的 MCP 工具，其执行结果不会预先传入。当前适配 MCP 2025-06-18 的 HTTP 请求/响应及有限 SSE 响应，带协议版本与会话头，支持工具列表分页；不含 stdio、OAuth 或持久 SSE 重连。Schema 校验为基础子集，复杂嵌套约束由工具服务继续校验。</p><h2>8. 接入、复现与可观察性</h2><p>正常启动仍使用 <code>python3 run.py</code>。教师进入“知识问答”，通过 AI 应用选择器切换应用；“应用与模板配置”编辑 JSON，可另设 id 创建资源；“上传 Skill”选择 Markdown 文件后绑定到应用。每次新应用对话有“查看本轮 LLM 请求与响应”入口，调用 <code>GET /api/traces/{id}</code>，仅本人、本班可读。</p><p>外部端点由管理员通过进程环境配置（Docker 可用 env_file），下面的地址仅为格式示例，需替换成实际服务；MCP allowed_tools 控制允许暴露的工具。token_env 指向进程中的密钥环境变量，切勿把真实密钥写入模板。</p><pre>export CAMPUS_EXTERNAL_TOOLS='[
  {"id":"school","kind":"mcp","url":"http://127.0.0.1:9000/mcp",
   "allowed_tools":["lookup"],"token_env":"SCHOOL_MCP_TOKEN"},
  {"id":"catalog","kind":"http","url":"http://127.0.0.1:9001/search",
   "description":"查询课程目录",
   "inputSchema":{"type":"object","properties":{"topic":{"type":"string"}},"required":["topic"]}}
]'
python3 run.py</pre><p>在应用的 tool_ids 中绑定 <code>school__lookup</code> 或 <code>catalog</code> 即可。工具结果可能含敏感业务数据，应仅配置适合自动调用的服务。traces 不记录认证请求头，但会保存问题、资料摘录和工具结果，应按教学数据管理；当前尚未实现保留期限自动清理。</p><pre>CAMPUS_WRITE_EVIDENCE=1 python3 -m unittest discover -s tests -v
python3 tools/build_verification_report.py
# 可选：启动临时数据库 + 本机确定性模型的演示服务
python3 tools/verification_demo.py
# 此演示不是在线 AI；地址 http://127.0.0.1:8879/chat</pre><p>兼容说明：旧客户端不携带 app_id 时仍走原 qa.py 教学问答；新增逐次 traces 和工具闭环针对携带 app_id 的新应用路径。历史会话标记 legacy，不混入新应用。原版向量检索与角色权限继续保留。</p><h2>9. 测试结果、限制与后续工作</h2><table><tr><th>测试组</th><th>数量</th><th>结论</th></tr><tr><td>原认证、问答与检索测试</td><td>30</td><td>29 通过，1 项真实 Qdrant 边界测试因缺依赖跳过</td></tr><tr><td>新增平台 HTTP 测试</td><td>10</td><td>全部通过：模板、知识库片段、上传技能、算术工具、MCP、HTTP 工具、鉴权、应用隔离、异常流及参数拒绝</td></tr><tr><td>合计</td><td>40</td><td>39 通过，1 跳过；详细日志见 test-results.txt</td></tr></table><p>当前结果证明功能实现与本机协议闭环。真实网关是否支持 tools、实际模型的引导行为和引用准确率、真实向量召回、第三方 MCP 服务的授权与兼容性、前端点击和视觉布局仍需独立验收。Skill 不提供脚本沙箱；模板与多技能总上下文尚未按模型 token 窗口裁剪；流式读超时不是总请求时限；调用日志暂未设置自动清理策略。</p><p>主要改动：platform_runtime.py（应用、资产、模型与工具运行时）、server.py（迁移和鉴权路由）、qa.py（新旧分流与应用隔离）、web/platform-ui.js、web/chat-ui.js、web/index.html、tests/test_platform.py。证据均来自临时测试数据，不包含现有班级资料。</p><h2>10. 可展开的完整报文证据</h2><p>下面保留本次测试生成的完整 JSON，可检索 request、response_chunks、response、tool_events 等字段。时间、随机会话 ID 与 localhost 端口在重跑时会变化，正文断言保持一致。与本页同目录另附 verification-evidence.json。</p>'''
labels={'knowledge':'A. 知识库检索：完整 LLM 请求与 SSE 返回','uploaded_skill':'B. 上传 Skill：完整正文及末尾标记','builtin_skill_execution':'C. 内置技能：计算工具执行及两次 LLM 请求','mcp':'D. MCP：初始化、工具发现、调用与结果回传','http_tool':'E. 外部 HTTP 工具闭环','no_hit':'F. 无命中：不调用模型','template':'G. 自定义模板：变量展开后传入 system'}
for key,label in labels.items():body+=f'<details><summary>{label}</summary><pre>{html.escape(json.dumps(evidence[key],ensure_ascii=False,indent=2))}</pre></details>'
body+='''<footer>技术依据：当前仓库代码与 tests/test_platform.py。MCP 协议参考 <a href="https://github.com/modelcontextprotocol/modelcontextprotocol/blob/main/docs/specification/2025-06-18/schema.mdx">官方 2025-06-18 Schema</a> 与 <a href="https://github.com/modelcontextprotocol/modelcontextprotocol/blob/main/docs/specification/2025-03-26/basic/transports.mdx">官方 Streamable HTTP 传输规范</a>；本项目实现范围以第 7 节为准。图 1-3 为依据当前代码绘制的流程示意，不是产品截图。</footer>'''
(OUT/'platform-verification-report.html').write_text(f'<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CampusClaw 功能与 LLM 请求验证报告</title><style>{style}</style></head><body><main>{intro}{body}</main></body></html>')
print('Created reports/platform-verification-report.html with 3 embedded SVG figures and 7 complete evidence cases.')
